<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { X } from '@lucide/vue'
import { db } from '../../db'
import { studentService } from '../../services/studentService'
import { useLessonStore } from '../../stores/useLessonStore'
import { useTermStore } from '../../stores/useTermStore'
import { useSchoolConfigStore } from '../../stores/useSchoolConfigStore'
import { getStudentGrade } from '../../utils/academic'
import type { LessonRecord, Student } from '../../types/schema'

const props = defineProps<{ editingId: string | null }>(); const emit = defineEmits<{ saved: [] }>()
const lessonStore = useLessonStore(); const termStore = useTermStore(); const schoolConfig = useSchoolConfigStore(); const students = ref<Student[]>([]); const studentSearch = ref(''); const selectedStudents = ref<Array<{ studentId: string; studentName: string; note: string }>>([]); const error = ref(''); const saving = ref(false)
const form = reactive({ grade: '', className: '', topic: '', date: new Date().toISOString().slice(0, 10), lessonPlanText: '', reflection: '' })
const activeStudents = computed(() => students.value.filter((student) => student.status === 'active'))
const gradeOptions = computed(() => schoolConfig.enabledGrades)
const classOptions = computed(() => form.grade ? schoolConfig.classesForGrade(form.grade) : [])
const candidates = computed(() => activeStudents.value.filter((student) => (!form.grade || getStudentGrade(student, termStore.currentTerm) === form.grade) && (!form.className || student.className === form.className) && (!studentSearch.value.trim() || [student.name, student.studentNo].join(' ').includes(studentSearch.value.trim())) && !selectedStudents.value.some((item) => item.studentId === student.id)).slice(0, 20))
function reset(record?: LessonRecord) { Object.assign(form, record ? { grade: record.grade, className: record.className, topic: record.topic, date: record.date, lessonPlanText: record.lessonPlanText, reflection: record.reflection } : { grade: '', className: '', topic: '', date: new Date().toISOString().slice(0, 10), lessonPlanText: '', reflection: '' }); selectedStudents.value = record ? record.notableStudents.map((item) => ({ ...item, studentName: item.studentName || students.value.find((student) => student.id === item.studentId)?.name || '未关联学生' })) : []; error.value = '' }
function addStudent(student: Student) { selectedStudents.value = [...selectedStudents.value, { studentId: student.id, studentName: student.name, note: '' }] }
function removeStudent(id: string) { selectedStudents.value = selectedStudents.value.filter((item) => item.studentId !== id) }
async function save() { if (!termStore.currentTermId || !form.grade || !form.className || !form.topic.trim() || !form.date) { error.value = '请完成年级、班级、课程主题和日期。'; return }; saving.value = true; error.value = ''; const draft = { termId: termStore.currentTermId, grade: form.grade, className: form.className, topic: form.topic.trim(), date: form.date, lessonPlanText: form.lessonPlanText.trim(), reflection: form.reflection.trim(), notableStudents: selectedStudents.value.map((item) => ({ ...item, note: item.note.trim() })) }; try { if (props.editingId) await lessonStore.updateLessonRecord(props.editingId, draft); else await lessonStore.addLessonRecord(draft); emit('saved'); lessonStore.closeForm() } catch { error.value = '保存教学记录失败，请稍后重试。' } finally { saving.value = false } }
watch(() => form.grade, () => { if (form.className && !classOptions.value.includes(form.className)) form.className = '' })
onMounted(async () => { await schoolConfig.load(); students.value = await studentService.list(); reset(props.editingId ? await db.lessonRecords.get(props.editingId) : undefined) })
</script>

<template><Teleport to="body"><div class="fixed inset-0 z-50 bg-stone-950/30" @click.self="lessonStore.closeForm()"><section class="ml-auto flex h-full w-full max-w-3xl flex-col overflow-y-auto bg-white p-6 shadow-2xl"><header class="flex items-start justify-between gap-4"><div><h2 class="text-lg font-semibold text-stone-800">{{ editingId ? '编辑心理课记录' : '新增心理课记录' }}</h2><p class="mt-1 text-sm text-stone-500">标记课堂观察学生后，其档案服务履历会自动关联课堂观察节点。</p></div><button type="button" class="rounded-lg p-1.5 text-stone-400 hover:bg-stone-100" @click="lessonStore.closeForm()"><X :size="18" /></button></header><p v-if="error" class="mt-4 rounded-lg bg-rose-50 px-3 py-2 text-sm text-rose-700">{{ error }}</p><div class="mt-5 grid gap-4 sm:grid-cols-2"><label class="text-sm font-medium text-stone-700">年级<select v-model="form.grade" class="mt-1.5 w-full rounded-lg border border-stone-200 px-3 py-2"><option value="">请选择年级</option><option v-for="item in gradeOptions" :key="item">{{ item }}</option></select></label><label class="text-sm font-medium text-stone-700">班级<select v-model="form.className" class="mt-1.5 w-full rounded-lg border border-stone-200 px-3 py-2"><option value="">请选择班级</option><option v-for="item in classOptions" :key="item">{{ item }}</option></select></label><label class="text-sm font-medium text-stone-700">课程主题<input v-model="form.topic" class="mt-1.5 w-full rounded-lg border border-stone-200 px-3 py-2" placeholder="如：认识情绪的信号" /></label><label class="text-sm font-medium text-stone-700">授课日期<input v-model="form.date" type="date" class="mt-1.5 w-full rounded-lg border border-stone-200 px-3 py-2" /></label></div><label class="mt-5 block text-sm font-medium text-stone-700">教案流程<textarea v-model="form.lessonPlanText" rows="5" class="mt-1.5 w-full rounded-lg border border-stone-200 p-3 text-sm leading-6" placeholder="记录导入、活动、讨论与总结等课堂流程。" /></label><label class="mt-5 block text-sm font-medium text-stone-700">课后反思<textarea v-model="form.reflection" rows="4" class="mt-1.5 w-full rounded-lg border border-stone-200 p-3 text-sm leading-6" placeholder="记录课堂反馈、调整方向与后续安排。" /></label><section class="mt-5 overflow-hidden rounded-xl border border-amber-200"><header class="border-b border-amber-100 bg-amber-50/40 p-4"><p class="text-sm font-semibold text-stone-800">课堂观察学生 <span class="text-amber-800">{{ selectedStudents.length }}</span></p><div class="mt-3 flex gap-2"><input v-model="studentSearch" class="min-w-0 flex-1 rounded-lg border border-stone-200 bg-white px-3 py-2 text-sm" placeholder="按姓名或学号搜索本班学生" /><span class="rounded-lg bg-white px-3 py-2 text-xs text-stone-500">{{ form.grade || '全部年级' }}{{ form.className }}</span></div></header><div class="grid sm:grid-cols-2"><div class="border-b border-stone-100 sm:border-b-0 sm:border-r"><p class="px-4 py-2 text-xs font-semibold text-stone-500">可标记学生</p><div class="max-h-48 overflow-y-auto"><button v-for="student in candidates" :key="student.id" type="button" class="flex w-full items-center justify-between border-t border-stone-50 px-4 py-2.5 text-left text-sm hover:bg-amber-50" @click="addStudent(student)"><span>{{ student.name }} <span class="text-xs text-stone-400">{{ student.studentNo }}</span></span><span class="text-xs font-semibold text-amber-800">+ 标记</span></button><p v-if="!candidates.length" class="px-4 py-6 text-center text-xs text-stone-400">请先选择班级或调整搜索条件</p></div></div><div><p class="px-4 py-2 text-xs font-semibold text-stone-500">已标记学生</p><div class="max-h-48 overflow-y-auto p-3"><p v-if="!selectedStudents.length" class="py-4 text-center text-xs text-stone-400">尚未标记学生</p><div v-for="item in selectedStudents" v-else :key="item.studentId" class="mb-2 rounded-lg bg-amber-50 p-2.5"><div class="flex items-center justify-between"><span class="text-sm font-medium text-stone-800">{{ item.studentName }}</span><button type="button" class="text-xs text-rose-600 hover:underline" @click="removeStudent(item.studentId)">移除</button></div><input v-model="item.note" class="mt-2 w-full rounded border border-amber-100 bg-white px-2 py-1.5 text-xs" placeholder="课堂观察，如：情绪低落、拒绝发言" /></div></div></div></div></section><footer class="mt-6 flex justify-end gap-2 border-t border-stone-100 pt-5"><button type="button" class="rounded-lg px-4 py-2 text-sm text-stone-600 hover:bg-stone-100" @click="lessonStore.closeForm()">取消</button><button type="button" :disabled="saving" class="rounded-lg bg-teal-700 px-4 py-2 text-sm font-semibold text-white disabled:opacity-50" @click="save">{{ saving ? '保存中…' : '保存记录' }}</button></footer></section></div></Teleport></template>
